def transform(grid):
    if not grid:
        return grid
    rows = len(grid)
    cols = len(grid[0])
    corner = grid[0][0]

    counts = {}
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    candidates = [c for c in counts if c != corner]
    background = max(candidates, key=lambda c: counts[c]) if candidates else None

    others = [c for c in counts if c != corner and c != background]
    target = max(others, key=lambda c: counts[c]) if others else None

    if background is not None and target is not None:
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == background:
                    grid[r][c] = target
    return grid
