def transform(grid):
    output = [row[:] for row in grid]
    # Find pattern colors in the grid
    pattern_colors = [2, 5]

    # For each cell that is canvas (3), replace based on position relative to pattern
    for r in range(len(output)):
        for c in range(len(output[r])):
            if output[r][c] == 3:
                # Calculate distance to the nearest pattern cell
                pattern_positions = []
                for pr in range(len(grid)):
                    for pc in range(len(grid[0])):
                        if grid[pr][pc] in pattern_colors:
                            pattern_positions.append((pr, pc))

                # Find closest pattern cell
                min_dist = float('inf')
                closest = None
                for pr, pc in pattern_positions:
                    dist = abs(r - pr) + abs(c - pc)
                    if dist < min_dist:
                        min_dist = dist
                        closest = (pr, pc)

                # Alternate replacement based on Manhattan distance parity
                dr, dc = abs(r - closest[0]), abs(c - closest[1])
                if (dr + dc) % 2 == 0:
                    output[r][c] = 5  # Even distance = center color
                else:
                    output[r][c] = 2  # Odd distance = border color

    return output
